"""19x19 rule fixtures: expectations are explicit, not generated by the engine."""
from copy import deepcopy
import unittest

from amphoreus_arena.go import GoGame
from test_go import play, position


class Go19EndgameTests(unittest.TestCase):
    def test_seki_shared_liberties_survive_scoring(self):
        game = GoGame(19)
        rows = ["B" * 9 + "W" * 10 for _ in range(19)]
        rows[8] = rows[9] = "B" * 9 + "." + "W" * 9
        game._board = tuple("".join(rows))
        game._seen = {game._board}
        # Both large groups share exactly K10 and K11. Whoever fills one first
        # can be captured at the other. Neither group is automatically dead.
        for side, first, second, lost in (("black", "K10", "K11", 172),
                                          ("white", "K11", "K10", 189)):
            attempt = deepcopy(game)
            attempt._current_player = side
            play(attempt, first, second)
            opponent = "white" if side == "black" else "black"
            self.assertEqual(attempt.captures[opponent], lost)
        before = game._board
        play(game, "pass", "pass")
        self.assertEqual(game._board, before)
        self.assertEqual(game.outcome()["score"], {
            "black": 171, "white": 195.5, "stones": {"black": 171, "white": 188},
            "territory": {"black": 0, "white": 0}, "neutral": 2, "komi": 7.5})

    def test_corner_and_edge_ko_are_atomic_at_all_rotations(self):
        # Corner ko at A1; edge ko at D1. Rotate to exercise every board edge.
        fixtures = [(("B2", "C1"), ("B1", "A2"), "A1", "B1"),
                    (("C2", "E2", "D3"), ("D2", "C1", "E1"), "D1", "D2")]
        for black, white, capture, recapture in fixtures:
            for rotation in range(4):
                def rotate(coord):
                    g = GoGame(19)
                    row, col = divmod(g._point(coord), 19)
                    for _ in range(rotation):
                        row, col = col, 18 - row
                    return g._coordinate(row * 19 + col)
                game = position(tuple(map(rotate, black)), tuple(map(rotate, white)), board_size=19)
                with self.subTest(capture=capture, rotation=rotation):
                    play(game, rotate(capture))
                    self.assertEqual(game.last_captures, [rotate(recapture)])
                    before = deepcopy(game.__dict__)
                    with self.assertRaisesRegex(ValueError, "superko"):
                        play(game, rotate(recapture))
                    self.assertEqual(game.__dict__, before)
                    play(game, "K10", "K11", rotate(recapture))
                    self.assertEqual(game.last_captures, [rotate(capture)])

    def test_capture_two_return_one_is_not_ko(self):
        game = position(black=("A2", "B2"), white=("A1", "B1", "C2", "D1"), board_size=19)
        initial = game._board
        play(game, "C1")
        self.assertEqual(set(game.last_captures), {"A1", "B1"})
        self.assertIn("B1", game.legal_actions())
        play(game, "B1")
        self.assertEqual(game.last_captures, ["C1"])
        self.assertNotEqual(game._board, initial)
        self.assertEqual(game.captures, {"black": 2, "white": 1})

    def test_scored_terminal_both_winners_and_draw(self):
        for komi, winner, margin in ((7.5, "white", 7.5), (-.5, "black", .5), (0, None, 0)):
            game = GoGame(19, komi=komi)
            game._board = tuple("BBBBBBBBB.WWWWWWWWW" * 19)
            game._seen = {game._board}
            play(game, "pass", "pass")
            result = game.outcome()
            self.assertEqual((result["winner"], result["margin"]), (winner, margin))
            self.assertEqual(result["score"]["neutral"], 19)
            self.assertEqual(game.legal_actions(), [])
            with self.assertRaisesRegex(ValueError, "finished"):
                play(game, "K10")
